test('isolatedControllerSnapshotsPrivateArgumentsBeforeYielding', async t => {
  const f = await fixture(t), before = fingerprint(f.database);
  const running = controller.runIsolatedReplay(f);
  f.expected.busiest = 99; f.cadence.factor = 1; f.config.senders.fiscal = 'live';
  let result;
  await assert.doesNotReject(async () => { result = await running; }, 'admitted arguments cannot change during copy/isolation awaits');
  assert.equal(result.admission.replay.counts.successful, 3);
  assert.equal(result.admission.replay.cadence.factor, 100); clean(f, before);
});

function prefixRuntime(f, prefix) {
  const path = join(f.codeRoot, 'runtime.mjs'), runtime = prefix + '\n' + readFileSync(path, 'utf8');
  writeFileSync(path, runtime);
  const manifest = JSON.parse(readFileSync(join(f.codeRoot, 'runtime-manifest.json'), 'utf8'));
  manifest.sha256 = createHash('sha256').update(runtime).digest('hex');
  writeFileSync(join(f.codeRoot, 'runtime-manifest.json'), JSON.stringify(manifest));
}

// The budget covers setup and copying too; an unresponsive worker cannot outlive the run.
test('isolatedControllerDeadlineCollectsAnUnresponsiveGenuineRuntime', async t => {
  const f = await fixture(t), before = fingerprint(f.database);
  prefixRuntime(f, 'await new Promise(resolve=>setTimeout(resolve,30000));');
  const start = performance.now();
  await assert.rejects(controller.runIsolatedReplay({ ...f, windowSeconds: 8 }), bad);
  assert.ok(performance.now() - start < 20000, 'deadline plus bounded cleanup must collect the worker');
  const entries = JSON.parse(readFileSync(f.journal.path, 'utf8')).localResources;
  assert.ok(entries.some(e => e.kind === 'replay-worker' && e.state === 'started'), 'reach the delayed worker');
  clean(f, before);
});

// Error paths must report lost ownership, preserving the recorded resources for explicit recovery.
test('isolatedControllerNeverClaimsCleanupAfterLosingItsOwnership', async t => {
  const f = await fixture(t), before = fingerprint(f.database), abort = new AbortController();
  prefixRuntime(f, 'await new Promise(resolve=>setTimeout(resolve,30000));');
  let changed = false;
  const poll = setInterval(() => {
    const entries = JSON.parse(readFileSync(f.journal.path, 'utf8')).localResources ?? [];
    if (!changed && entries.some(e => e.kind === 'replay-worker' && e.state === 'started')) {
      changed = true; writeFileSync(join(f.root, '.cloud-cost-owner'), '0'.repeat(64), { mode: 0o600 }); abort.abort();
    }
  }, 10);
  try { await assert.rejects(controller.runIsolatedReplay({ ...f, signal: abort.signal }), bad); }
  finally { clearInterval(poll); writeFileSync(join(f.root, '.cloud-cost-owner'), f.journal.token, { mode: 0o600 }); }
  assert.equal(changed, true);
  assert.notEqual(docker(['ps', '-aq', '--filter', 'label=io.waitron.cloud-cost.owner=' + f.journal.token]), '');
  assert.equal(existsSync(join(f.root, 'isolated-replay')), true);
  assert.deepEqual(fingerprint(f.database), before);
  assert.equal(JSON.parse(readFileSync(f.journal.path, 'utf8')).localResources.some(e => e.kind === 'isolated-replay' && e.state === 'removed'), false);
});

// Returning clean metadata is insufficient if a private child stream reaches the caller.
test('isolatedControllerSuppressesTheActualWorkerOutput', async t => {
  const f = await fixture(t), before = fingerprint(f.database);
  prefixRuntime(f, 'console.log("PRIVATE_SYNTHETIC_STDOUT");console.error("PRIVATE_SYNTHETIC_STDERR");');
  const configPath = join(f.root, 'caller-config.json'); writeFileSync(configPath, JSON.stringify(f), { mode: 0o600 });
  const result = spawnSync(process.execPath, ['--input-type=module', '-e',
    `import {readFileSync} from 'node:fs';
     import {runIsolatedReplay} from ${JSON.stringify(new URL('../isolated-replay.mjs', import.meta.url).href)};
     await runIsolatedReplay(JSON.parse(readFileSync(process.argv[1],'utf8')));process.stdout.write('DONE');`, configPath],
    { env: { PATH: process.env.PATH, LANG: 'C', TZ: 'UTC' }, timeout: 30000, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  assert.equal(result.status, 0); assert.equal(result.stdout, 'DONE'); assert.equal(result.stderr, ''); clean(f, before);
});

// A different directory at the same pathname is not the directory this invocation created.
test('isolatedControllerPreservesAReplacedPrivateDirectory', async t => {
  const f = await fixture(t), before = fingerprint(f.database), abort = new AbortController();
  const path = join(f.root, 'isolated-replay'), retained = join(f.root, 'retained-private-state'); let changed = false;
  const poll = setInterval(() => {
    const entries = JSON.parse(readFileSync(f.journal.path, 'utf8')).localResources ?? [];
    if (!changed && entries.some(e => e.kind === 'replay-worker' && e.state === 'started')) {
      changed = true; renameSync(path, retained); mkdirSync(path, { mode: 0o700 });
      writeFileSync(join(path, 'replacement-sentinel'), 'preserve replacement', { mode: 0o600 }); abort.abort();
    }
  }, 10);
  try { await assert.rejects(controller.runIsolatedReplay({ ...f, signal: abort.signal }), bad); }
  finally { clearInterval(poll); }
  assert.equal(changed, true); assert.equal(existsSync(path), true, 'preserve a replacement directory');
  assert.equal(readFileSync(join(path, 'replacement-sentinel'), 'utf8'), 'preserve replacement');
  assert.equal(existsSync(retained), true, 'retain the recorded state for explicit recovery');
  assert.deepEqual(fingerprint(f.database), before);
  assert.equal(docker(['ps', '-aq', '--filter', 'label=io.waitron.cloud-cost.owner=' + f.journal.token]), '');
  assert.equal(docker(['network', 'ls', '-q', '--filter', 'label=io.waitron.cloud-cost.owner=' + f.journal.token]), '');
});


// The command must use the real controller and publish only its admitted aggregate fields.
const commandPath = new URL('../cli.mjs', import.meta.url).pathname;
function localCommand(f) {
  const path = join(f.root, 'private-command.json');
  writeFileSync(path, JSON.stringify({ stage: 'replay-admission', ...f }), { mode: 0o600 });
  return [commandPath, 'local', '--private-config', path, '--cadence', f.cadence.mode,
    '--window-seconds', String(f.windowSeconds)];
}
test('localCommandRunsTheGenuineWriterAndSuppressesPrivateOutput', async t => {
  const f = await fixture(t), before = fingerprint(f.database);
  prefixRuntime(f, 'console.log("PRIVATE_SYNTHETIC_STDOUT");console.error("PRIVATE_SYNTHETIC_STDERR");');
  const command = localCommand(f), configBefore = readFileSync(command[3]);
  const result = spawnSync(process.execPath, command, { env: { PATH: process.env.PATH, LANG: 'C', TZ: 'UTC' },
    timeout: 30000, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  assert.equal(result.status, 0); assert.equal(result.stderr, '');
  const output = JSON.parse(result.stdout);
  assert.deepEqual(Object.keys(output).sort(), ['admission', 'cleanup', 'costMeasured', 'isolation', 'stage']);
  assert.equal(output.stage, 'replay-admission'); assert.equal(output.costMeasured, false);
  assert.deepEqual(output.admission.replay.counts, { expected: 3, attempted: 3, successful: 3, failed: 0 });
  assert.deepEqual(output.admission.integrity, { ok: true, issues: 0 });
  assert.deepEqual(output.isolation, { blockedConnections: 3, blockedDns: 2, localControl: true });
  assert.deepEqual(output.cleanup, { workerContainers: 0, networks: 0, privateCopies: 0 });
  assert.equal(/PRIVATE_|2026-|\/state|taxId|locationId|sha256:|ownership|journal/.test(result.stdout), false);
  assert.deepEqual(readFileSync(command[3]), configBefore, 'caller owns the config'); clean(f, before);
});

// Losing either signal handler kills the client before its recorded worker can be collected.
for (const signal of ['SIGINT', 'SIGTERM']) {
  test('localCommandWaitsForOwnedCleanupOn_'+signal, async t => {
    const f = await fixture(t), before = fingerprint(f.database);
    prefixRuntime(f, 'await new Promise(resolve=>setTimeout(resolve,30000));');
    const { spawn } = await import('node:child_process');
    const child = spawn(process.execPath, localCommand(f), { env: { PATH: process.env.PATH, LANG: 'C', TZ: 'UTC' },
      stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '', stderr = '', sent = false, timer;
    child.stdout.on('data', chunk => { stdout += chunk; }); child.stderr.on('data', chunk => { stderr += chunk; });
    const closed = new Promise((resolve, reject) => { child.once('error', reject); child.once('close', (status, signal) => resolve({ status, signal })); });
    const poll = setInterval(() => {
      const entries = JSON.parse(readFileSync(f.journal.path, 'utf8')).localResources ?? [];
      if (!sent && entries.some(e => e.kind === 'replay-worker' && e.state === 'started')) { sent = true; child.kill(signal); }
    }, 10);
    try {
      timer = setTimeout(() => child.kill('SIGKILL'), 20000);
      const result = await closed;
      assert.equal(sent, true, 'reach the admitted worker before signalling');
      assert.deepEqual(result, { status: 1, signal: null });
      assert.equal(stdout, ''); assert.equal(stderr, 'Cloud cost local command refused.\n'); clean(f, before);
    } finally { clearInterval(poll); clearTimeout(timer); }
  });
}

